  await f.evaluate(()=>{window.__LTS_V168_STATE.expense.key='12m';});await f.locator('[data-v235-open]').click();await f.waitForFunction(text=>document.getElementById('v235-history-dialog')?.textContent.includes(text),latest?'Não há registros históricos por total':'Não há composição pendente');assert.equal(calls.filter(x=>x.name===inventoryRpc).at(-1).args.p_from,'2025-11-01');await f.locator('[data-v235-close]').click();
