   await f.locator('[data-v235-cycle="1"]').first().click();await f.waitForSelector('[data-v237-excluded]');assert.equal(await f.locator('[data-v235-source-item]').count(),3);assert.match(await f.locator('.v235-partial-totals').innerText(),/85,00.*0,00/s);await f.locator('[data-v237-formula] summary').click();assert.match(await f.locator('[data-v237-formula]').innerText(),/110,00.*25,00.*85,00/s);assert.match(await f.locator('[data-v237-formula]').innerText(),/SUMIFS/);await f.locator('[data-v235-close]').click();
